import{_ as r,l as i,o as a,c as d,v as t,p as n,x as l,d as c,i as s,S as A}from"./chunks/framework.InCnrqk-.js";const _=JSON.parse('{"title":"AMX 内核与至强加速","description":"","frontmatter":{"title":"AMX 内核与至强加速","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/amx-kernel.md","filePath":"llm/amx-kernel.md","lastUpdated":1789023840000}'),T={name:"llm/amx-kernel.md"};function p(M,e,m,X,S,I){const o=i("Mermaid");return a(),d("div",null,[e[1]||(e[1]=t('<h1 id="amx-内核与至强加速" tabindex="-1">AMX 内核与至强加速 <a class="header-anchor" href="#amx-内核与至强加速" aria-label="Permalink to &quot;AMX 内核与至强加速&quot;">​</a></h1><div class="epigraph"><p>八个二维 tile 寄存器加一条 TMUL：把「子矩阵 × 子矩阵」写成 ISA，而不是用 AVX-512 一遍一遍点积。</p><footer>—— Intel AMX 内建函数示例与 Intel 64 / IA-32 软件开发者手册中的 tile / TMUL 描述</footer></div><p>Advanced Matrix Extensions 从第四代至强可扩展处理器（Sapphire Rapids）进入服务器 x86。相对 AVX-512 的一维 SIMD，AMX 提供可编程形状的二维寄存器（tile）和 Tile Matrix Multiply（TMUL）加速器。Linux 不把 8KB 量级的 XTILEDATA 无条件加进每个任务的 FPU 状态，应用程序必须 <code>arch_prctl</code> 申请。本篇按 Intel 编程文档与内核 XSTATE 说明写内核形态、权限模型与 MoE 推理里该怎么铺核，不编造未在产品简报页核对过的单核 TOPS。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Transformer 与 MoE 专家的热循环是 GEMM。GPU 有 Tensor Core；CPU 一侧若仍把 \\(C \\mathrel{+}= AB\\) 拆成向量 FMA，L1/L2 会被反复冲刷，算术强度低于加速器。AVX-512 对 decode 这种「一行乘一块权重」够用，对 prefill 里每个专家几十到上百 token 的小批量矩阵则偏细。AMX 要解决的是：在至强上给 INT8 / BF16 矩阵乘一条与 GPU 张量核同构的原语，并让操作系统扛得住每任务多出来的大状态。</p><p>状态是真问题。Intel 与内核补丁写明：TMM 寄存器今天约 8KB，架构上可到 64KB。若给每个进程无条件分配，内存与上下文切换会被空任务拖死。于是 AMX 走动态 XSTATE：XFD（eXtended Feature Disabling）在首次使用时 #NM，内核再分配大 buffer。</p><h3 id="palette-先配置-再计算" tabindex="-1">Palette：先配置，再计算 <a class="header-anchor" href="#palette-先配置-再计算" aria-label="Permalink to &quot;Palette：先配置，再计算&quot;">​</a></h3><p>使用 TMUL 之前必须加载 64 字节的 tile 配置。Palette 0 是初始态；palette 1 把 <strong>8KB 分给 8 个 tile</strong>，每个最多 <strong>16 行 × 64 字节</strong>。配置结构含 palette_id、start_row、每个 tile 的 <code>colsb</code>（每行字节）和 <code>rows</code>。<code>_tile_loadconfig</code> 写入后，后续 <code>TDPBSSD</code> 一类指令会按这份元数据检查形状是否构成合法矩阵乘。配置按线程生命期保持，直到 <code>_tile_release</code> 或改配置。Intel 示例用 16×64 的 INT8 A/B 累加到 16×16 INT32 C，正好铺满一块 tile。</p><p><span class="marginnote">Stride 不是配置的一部分。大矩阵按 16×64 切块时，最后一块可以更窄，只要 <code>TILELOADD</code> 的 stride 指向行主序里下一行。配置描述的是寄存器形状，不是内存里整张 \\(M\\times K\\) 的合同尺寸。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>Linux 用户态顺序是：<code>ARCH_GET_XCOMP_SUPP</code> 查内核是否支持 tile；再 <code>ARCH_REQ_XCOMP_PERM</code> 申请 <code>XFEATURE_XTILEDATA</code>。未申请就执行 AMX，#NM 处理会送 SIGILL；申请后首次使用才分配大 xstate，分配失败则 SIGSEGV。权限按进程授予、不可撤回，<code>exec</code> 清掉。信号栈必须够大：glibc 2.34 起 <code>MINSIGSTKSZ</code> / <code>SIGSTKSZ</code> 变成运行时查询，老二进制写死 2KB 会在 AMX 进程里炸。虚拟化路径上，QEMU 需在 AMX 主机上把特性传进客户机；宿主机与客户机的 XFD 彼此独立。</p><p>指令序列在 Intel 示例里是四步：loadconfig → <code>TILELOADD</code> 三块（A、B、累加器）→ <code>TDPBSSD</code>（或 UD/SU/UU 变体）→ <code>TILESTORED</code>。<code>TDPBSSD</code> 把 tmm2 与 tmm3 里相邻 4 个有符号字节做点积，四个 32 位中间结果加到 tmm1。BF16 走另一组 TMUL。这只是单次 tile 乘；生产核要在外层循环切 K、切 N，并处理 pack、量化反缩放与偏置。</p>',12)),(a(),n(A,null,{default:l(()=>[s(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20PERM%5B%22arch_prctl%20%E7%94%B3%E8%AF%B7%20XTILEDATA%22%5D%20--%3E%20CFG%5B%22_tile_loadconfig%20palette%201%22%5D%0A%20%20CFG%20--%3E%20LD%5B%22TILELOADD%20%E5%AD%90%E7%9F%A9%E9%98%B5%22%5D%0A%20%20LD%20--%3E%20MUL%5B%22TMUL%EF%BC%9ATDPBSSD%20%2F%20BF16%22%5D%0A%20%20MUL%20--%3E%20ST%5B%22TILESTORED%22%5D%0A%20%20ST%20--%3E%20REL%5B%22_tile_release%22%5D%0A"})]),fallback:l(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<h3 id="至强上的-llm-核该铺什么" tabindex="-1">至强上的 LLM 核该铺什么 <a class="header-anchor" href="#至强上的-llm-核该铺什么" aria-label="Permalink to &quot;至强上的 LLM 核该铺什么&quot;">​</a></h3><p>KTransformers 一类 MoE 核把专家权重切成贴 L2 的块，块内再切 AMX tile，输入放 L3，见 <a href="/llm/ktransformers-hybrid">KTransformers 混合推理</a>。oneMKL、Intel 优化的 TensorFlow / PyTorch 在 SPR 上也会走 AMX，那是框架路径，不一定按专家形状 pack。自己写核时：INT8 累加到 INT32 要在 tile 外做 requant；decode 每专家 token 很少时，铺满 16×64 可能比 AVX-512 更亏——论文里 ARI 低时要换指令，不是 AMX 「永远更快」。NUMA 上 tile 配置是每线程的，权重副本必须本节点；跨路去取 8KB 的源操作数，TMUL 再快也被内存墙挡住。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>从线性代数看，一块 INT8 tile 乘是</p> \\[C_{16\\times 16} \\mathrel{+}= A_{16\\times 64}\\, B_{16\\times 64}^{\\top} \\]<p>（\\(B\\) 在内存里按 TMUL 要求的布局摆），\\(K\\) 维 64 字节 = 64 个 INT8。大 GEMM 是这些 tile 沿 \\(K\\) 累加、沿 \\(M/N\\) 平移。Intel 写明 TMUL 执行时会动态检查 tile 最大尺寸与矩阵维是否匹配；配错形状不是静默错结果，而是指令侧的合法性失败。XSAVE 组件是 XTILECFG 与 XTILEDATA：前者小，后者大。内核默认 XCR0.AMX=1，但 XTILEDATA 要用户申请，这是「硬件已枚举、OS 仍按需分配」的折中。</p><p>上下文切换：不用 AMX 的任务保持短 xstate；用 AMX 的任务多 8KB 级保存/恢复。intel_idle 在 SPR 上会清 TMM，避免休眠状态带着脏 tile。这对延迟敏感的 decode 意味着：线程应绑核、少迁移，避免把 AMX 任务和大量短命线程挤在同一核上反复 XSAVE。</p><p><span class="marginnote">CPUID 枚举指令，XGETBV 看 OS 是否打开 XCR0，再加 <code>arch_prctl</code> 才是 Linux 上的完整三重检查。只查 CPUID 在容器或旧内核里会 SIGILL。编译器侧 GCC 11 / LLVM 12 起有内建函数；生产更常见的是 oneDNN 或手写汇编循环，而不是把示例 <code>test-amxtile</code> 嵌进服务。</span></p><h3 id="和-avx-512、gpu-张量核的分工" tabindex="-1">和 AVX-512、GPU 张量核的分工 <a class="header-anchor" href="#和-avx-512、gpu-张量核的分工" aria-label="Permalink to &quot;和 AVX-512、GPU 张量核的分工&quot;">​</a></h3><p>AVX-512 寄存器窄、指令开销低，适合低 ARI 与非矩阵算子（softmax、layernorm、路由）。AMX 适合高 ARI 的专家 GEMM 与 prefill。GPU Tensor Core 的形状与调度由 CUDA 生态包圆；AMX 要把 cache 层级写进核，因为没有同等的共享存储编程模型。混合推理里常见的做法是同一块权重布局同时喂 AMX 与 AVX-512，运行时按 token/专家比切换，避免两套 pack。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>单芯片峰值 TOPS 随 SKU、频率、L2、内存通道而变，应读当时那一颗至强的产品简报，不要把某篇 MoE 核论文的持续 TFLOPS 当成铭牌。后续至强代际扩展了数据类型（文档按代数列出），写核要以目标 CPUID 为准，而不是假设 SPR 的 INT8/BF16 全集在所有至强上可用。信号栈、seccomp、旧 glibc、未转发 AMX 的虚机，是部署期最高频的「有 AMX 却跑不起来」。</p><p>不要在无 AMX 的客户端 CPU 上假设同一套 INT4 专家核。不要让每个短请求线程都去申请 XTILEDATA——权限是进程级的，但大 xstate 是任务级分配，线程爆炸会把内存吃成「8KB × 线程数」。容器要明确允许 <code>arch_prctl</code> 与足够的 sigaltstack。</p><p>功耗与频率也是核外的约束。TMUL 把矩阵乘收进加速器，但 L2 未命中时仍要付内存通道的电与延迟；双路满核跑专家时，内存带宽墙往往先于「tile 是否打满」出现。BIOS 若关掉 AMX 或把子 NUMA 切得过碎，用户态只会看见 SIGILL 或吞吐掉到 AVX 路径。选型时先确认 CPUID 叶子、内核版本与 glibc，再谈 INT8 相对 BF16 的加速比。生产核还要处理 saturating 累加后的 requant、偏置与残差加回，这些步骤仍在 AVX 或标量里，不能假装一条 <code>TDPBSSD</code> 等于完整的专家 FFN。</p><p><span class="marginnote">出处：Intel <em>Code Sample: AMX Intrinsics Functions</em>（palette 1、16×64、TDPBSSD）；Linux 内核文档 <em>Using XSTATE features</em>（<code>ARCH_REQ_XCOMP_PERM</code>、XFD）；LWN / 内核补丁说明中的 8KB TMM 与动态分配。峰值 TOPS 以具体至强简报为准，本篇不填写。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>AMX 用 8 个 tile（palette 1：每 tile 最多 16×64 字节，共 8KB）加 TMUL 做 INT8/BF16 矩阵乘。</li><li>Linux 上必须申请 XTILEDATA；状态按需分配，避免给所有任务摊 8KB。</li><li>LLM 核要把专家 GEMM 切到 tile，并在低 ARI 时让位给 AVX-512。</li><li>配置一次、循环 load/compute/store；stride 处理尾块。</li><li>不要把未核对 SKU 的 TOPS 写进容量规划。</li><li>出处：Intel AMX 编程示例与内核 XSTATE 文档。</li></ul>',17))])}const h=r(T,[["render",p]]);export{_ as __pageData,h as default};
